#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.01535425, 0.452048615, -0.02077364], 'basis': [[-0.0, 0.9973157674694848, 0.0732206252141611], [0.4290077057401799, -0.06614025148598207, 0.9008761599403763], [0.903300829411524, 0.03141221243598882, -0.4278561493005904]], 'axis': [0.0732206252141611, 0.9008761599403763, -0.4278561493005904], 'zmin': -0.0035211958703858784, 'zmax': 0.012593479285267552, 'profiles': [{'outer': [[-0.03244828772348182, 0.07091791056310831], [-0.030926187968132422, 0.07380473341263416], [-0.030527479307989172, 0.07702803486862869], [-0.029953433309590948, 0.08016742929461397], [-0.028080654587654557, 0.08271334329811672], [-0.025051235925592316, 0.08360509783170622], [-0.021106088645975532, 0.08186156284530662], [-0.017265786795050305, 0.07909488331984708], [-0.014414675502254823, 0.07691833841355077], [-0.012251119744553807, 0.07499745928337134], [-0.008729106916808924, 0.07114775368365739], [-0.008159101303014444, 0.07088800417159301], [-0.007366712303751204, 0.07117968878625354], [-0.005666404636356302, 0.07098139507430863], [-0.0013645911372813172, 0.07018359200485232], [0.0003063571316516802, 0.06975990516367853], [0.0009293056213182136, 0.06916191352607787], [0.0016384548647848537, 0.06915738508819991], [0.0062890513699904406, 0.07156955504046808], [0.008926762754516666, 0.07258832365882723], [0.01223056206915718, 0.07363027967580361], [0.01667253761771743, 0.07480533314509015], [0.020739336049765706, 0.07500512870780068], [0.022960777323080352, 0.07313689303279682], [0.023534715736957416, 0.07007961085916484], [0.02270212312790118, 0.06694422520772403], [0.021772563560549758, 0.06376575104796868], [0.0220164364542382, 0.06057776429464704], [0.02216333809955435, 0.05738992333293321], [0.0209800798469965, 0.054292661113231354], [0.0184686738216963, 0.05250422322820798], [0.01459382428013167, 0.053118901000457956], [0.010646519253282178, 0.054747105241228174], [0.005349537429068754, 0.05679500492550822], [0.0029400629050448054, 0.057906223177655924], [0.0005717199864139847, 0.05863660224349754], [-0.0003127708853846664, 0.05816271185045731], [-0.0012902744650106926, 0.05740035794894984], [-0.005973101395322894, 0.05867236793615598], [-0.010559889815794228, 0.059102565397977834], [-0.011171039905212997, 0.06013249818301826], [-0.011741076002401067, 0.06091132362546795], [-0.014394419582890592, 0.06110107673959191], [-0.017200543571337944, 0.060996786427405233], [-0.028033205597215255, 0.061209656331610726], [-0.0321576054020072, 0.06211452251035102], [-0.033919542409372505, 0.06477663363589373], [-0.03385285426498523, 0.06807842931690229]], 'holes': []}, {'outer': [[-0.023113773805788877, -0.06406584486015682], [-0.021332182283873107, -0.061552597698967634], [-0.01750551766408773, -0.060940818682559746], [-0.01323122044250551, -0.06123239987111445], [-0.007571018967473744, -0.06145011308099992], [-0.0049773963491212625, -0.06173199211446544], [-0.002575769812100081, -0.06161712712734513], [-0.0013309127029653895, -0.05985901631053297], [0.0036457084849708674, -0.059547300938795414], [0.008254098288260093, -0.05842867832872171], [0.009940764434438086, -0.05970398113593589], [0.012428613175644674, -0.0590821534526181], [0.015075161509560987, -0.05805851606438196], [0.020984321328868766, -0.05617439306073014], [0.02540965055172967, -0.05464330250295499], [0.02962633736755994, -0.0540897836658226], [0.032222010601478154, -0.05595418530139772], [0.03323189983443379, -0.059081429430680045], [0.03284402635261331, -0.06223864410061882], [0.032321973331247526, -0.06543322188354306], [0.0330429209749619, -0.06859617585634441], [0.033569942376531624, -0.0717156304731901], [0.032604202423682734, -0.0746847376305356], [0.03004283597089922, -0.07657303738467941], [0.025688041105518106, -0.07626974453053231], [0.021114791817527925, -0.07498966872968361], [0.0176855808186451, -0.07390122146618665], [0.0150419726054606, -0.07282170389182693], [0.010463870649087622, -0.0704508857098861], [0.009816297733008067, -0.07044728523526791], [0.009166999112535218, -0.07094262970210106], [0.007473507689244613, -0.07135215132929083], [0.005315737338457815, -0.0717134657968327], [0.003104117113729893, -0.07201584242606919], [0.001381235808583832, -0.07213169122526024], [0.000588881582791215, -0.07181775949441792], [-5.951111841704252e-05, -0.07195006315267201], [-0.001755899308814733, -0.07364089668821469], [-0.003621732298886161, -0.07565906931912841], [-0.0057598648425765415, -0.07746338816716679], [-0.008550276149564325, -0.07950073641030116], [-0.012358317091989325, -0.08201871221452607], [-0.016110561292205762, -0.08350711442539652], [-0.018793259981080133, -0.08241809208408629], [-0.020365315420981567, -0.07973808747539238], [-0.020608238868684577, -0.0765303561142761], [-0.020772826709898464, -0.07323339857880327], [-0.022053958918820595, -0.07029426799224184], [-0.023238136586824498, -0.06735526894159334]], 'holes': []}], 'simplify_tolerance': 3.3422442451420546e-05, 'sketch_entity_count': 97}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
